 @Test void historyMaxCountsPreserveWholeRowsAndNoTopReferentialNarrowing() throws Exception {actor("PRO","HUMAN","ACTIVE",List.of());var sets=historySets();var enc=encounterRow();enc.put("status","FINALIZED");enc.put("activePatient",null);enc.put("finalizedAt",TIME);for(int set=0;set<3;set++){int size=set==1?1000:200;var source=set==0?enc:set==1?entryRow():documentRow();var rows=new ArrayList<Map<String,Object>>();for(int i=0;i<size;i++){var row=new LinkedHashMap<>(source);row.put("id",UUID.nameUUIDFromBytes((set+"-synthetic-"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());rows.add(row);}sets.set(set,rows);}history(sets);var out=store.history(request,PATIENT);assertEquals(200,((List<?>)out.get("encounters")).size());assertEquals(1000,((List<?>)out.get("entries")).size());assertEquals(200,((List<?>)out.get("documents")).size());assertEquals(1,calls.size());}
 @Test void historyJsonScalarsNullAndTransactionFailuresAreSafe() throws Exception {actor("AUD","HUMAN","SUSPENDED",List.of());for(Object value:Arrays.asList(null,"synthetic",true,new BigDecimal("999999999999999999.123"),Arrays.asList(null,"value"))){var sets=historySets();sets.get(1).getFirst().put("payload",value);history(sets);var out=store.history(request,PATIENT);assertEquals(value,((List<Map<String,Object>>)out.get("entries")).getFirst().get("payload"));}history(historySets());manager.failCommit=true;safe(()->store.history(request,PATIENT));history(historySets());assertThrows(RuntimeException.class,()->manager.outer(()->{store.history(request,PATIENT);throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());}
 @Test void newSpVendorErrorsAndDirectHistoryGuardsDoNotRetry(){actor("REC","HUMAN","ACTIVE",List.of("PORTAL"));assertEquals(403,assertThrows(ApiException.class,()->store.history(request,PATIENT)).status);for(int code:List.of(51000,51001,51002,51003,51004,51005)){doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.link(request,PATIENT,linkInput()));assertEquals(Map.of(51000,400,51001,403,51002,404,51003,409,51004,403,51005,409).get(code),e.status);assertFalse(e.toString().contains("private"));assertNull(e.getCause());}actor("PRO","HUMAN","ACTIVE",List.of());doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51002))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(404,assertThrows(ApiException.class,()->store.history(request,PATIENT)).status);verify(executor,times(7)).execute(any(),any(),any(Object[].class));}

 static Map<String,Object> readLink(){var row=new LinkedHashMap<String,Object>();row.put("tenantId",TENANT);row.put("patientId",PATIENT);row.put("userId",ID);row.put("userName","");row.put("relationship","");row.put("active",false);row.put("scopes",new ArrayList<>(List.of("OLD","OLD","DOCUMENTS")));row.put("email","private");return row;}
 void readRequest(){request.setAttribute("health.requestId",ID);}
 @Test void linksPreserveSqlOrderHistoricalValuesAndImmutableSevenFieldProjection(){readRequest();actor("REC","ANIMAL","SUSPENDED",List.of());var first=readLink();first.put("userName","Zed");var second=readLink();second.put("userId",TENANT);second.put("userName","Alpha");second.put("active",true);second.put("scopes",List.of());rows(List.of(first,second));var out=store.links(request,PATIENT,50,0);assertEquals(List.of("Zed","Alpha"),out.stream().map(r->r.get("userName")).toList());assertEquals(false,out.getFirst().get("active"));assertEquals(true,out.getLast().get("active"));assertEquals(Set.of("tenantId","patientId","userId","userName","relationship","active","scopes"),out.getFirst().keySet());assertEquals(List.of("OLD","OLD","DOCUMENTS"),out.getFirst().get("scopes"));((List<?>)first.get("scopes")).clear();assertEquals(3,((List<?>)out.getFirst().get("scopes")).size());assertThrows(UnsupportedOperationException.class,out::clear);assertThrows(UnsupportedOperationException.class,out.getFirst()::clear);assertThrows(UnsupportedOperationException.class,((List<?>)out.getFirst().get("scopes"))::clear);assertEquals(List.of(SqlServerProcedure.PATIENT_LINKS_LIST),calls);assertEquals(List.of(PATIENT,50,0),args.getFirst());assertEquals(List.of("begin:0","commit"),manager.events);assertEquals("private",first.get("email"));}
 @Test void linksClampsPaginationAndParticipatesInOuterTransaction(){readRequest();rows(List.of());assertEquals(List.of(),store.links(request,PATIENT,0,-9));assertEquals(List.of(PATIENT,1,0),args.getLast());rows(List.of());manager.outer(()->store.links(request,PATIENT,999,Integer.MAX_VALUE));assertEquals(List.of(PATIENT,200,Integer.MAX_VALUE),args.getLast());assertEquals(2,manager.events.stream().filter("commit"::equals).count());}
 @Test void linksRejectEveryMalformedRequiredFieldAndRollback(){readRequest();var bad=new LinkedHashMap<String,List<Object>>();bad.put("tenantId",Arrays.asList(null,ID,"bad",7));bad.put("patientId",Arrays.asList(null,TENANT,"bad"));bad.put("userId",Arrays.asList(null,"bad",ID.toUpperCase(Locale.ROOT),1));bad.put("userName",Arrays.asList(null,1,"x".repeat(161)));bad.put("relationship",Arrays.asList(null,1,"x".repeat(81)));bad.put("active",Arrays.asList(null,0,1,"true"));bad.put("scopes",Arrays.asList(null,"[]",Map.of(),List.of(1),Arrays.asList((Object)null),List.of(Map.of("scope","OLD"))));for(var entry:bad.entrySet())for(Object value:entry.getValue()){var row=readLink();row.put(entry.getKey(),value);rows(List.of(row));safe(()->store.links(request,PATIENT,50,0));assertEquals("rollback",manager.events.getLast());}for(String key:readLink().keySet())if(!key.equals("email")){var row=readLink();row.remove(key);rows(List.of(row));safe(()->store.links(request,PATIENT,50,0));}assertTrue(calls.stream().allMatch(p->p==SqlServerProcedure.PATIENT_LINKS_LIST));}
