 @Test void linksDirectCallerRoleAndCanonicalContextDefenseBeforeBusinessCall(){readRequest();for(var roles:List.of(List.of("SAD"),List.of("SOP"),List.of("PAC"),List.of("RES"),List.of("PRO"),List.of("ASI"),List.of("AUD"),List.of("ADM","PAC"),List.of("REC","RES"),List.of("ADM","SAD"),List.<String>of())){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,roles,"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->store.links(request,PATIENT,50,0)).status);}actor("ADM","HUMAN","SUSPENDED",List.of());assertEquals(400,assertThrows(ApiException.class,()->store.links(request,"bad",50,0)).status);for(String bad:List.of("bad",ID.toUpperCase(Locale.ROOT))){request.setAttribute("health.requestId",bad);safe(()->store.links(request,PATIENT,50,0));}request.removeAttribute("health.requestId");safe(()->store.links(request,PATIENT,50,0));readRequest();for(String token:List.of("bad","g".repeat(64))){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("ADM"),token));safe(()->store.links(request,PATIENT,50,0));}actor("ADM","HUMAN","ACTIVE",List.of());request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","DOCTOR","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->store.links(request,PATIENT,50,0)).status);verifyNoInteractions(executor);}
